"""Summarize saved Qwen outputs without generation or organizer-label access."""
from pathlib import Path
import argparse,json,csv,collections,html
p=argparse.ArgumentParser();p.add_argument('--outputs',type=Path,required=True);p.add_argument('--prepared',type=Path,required=True);p.add_argument('--destination',type=Path,required=True);a=p.parse_args();a.destination.mkdir(parents=True,exist_ok=True)
reports=[json.loads(l) for l in (a.prepared/'inputs.jsonl').read_text().splitlines()]
order=['control-1','candidate-1','candidate-2','control-2'];runs={}; flat=[]
for block in order:
 folder=a.outputs/block
 if not (folder/'raw.jsonl').exists():continue
 raws=[json.loads(l) for l in (folder/'raw.jsonl').read_text().splitlines()]
 parsed={r['attempt']:r for r in [json.loads(l) for l in (folder/'parsed.jsonl').read_text().splitlines()]} if (folder/'parsed.jsonl').exists() else {}
 runs[block]=[]
 for raw in raws:
  r=parsed.get(raw['attempt'],{});g=raw['generation'];entry={'case_index':raw['case_index'],'raw':g['raw_output'],'generation_status':g['generation_status'],'seconds':g['runtime_seconds'],'output_tokens':g['output_tokens'],'peak_gib':raw['gpu_peak_allocated_gib'],'primary':r.get('primary_v2',{}),'secondary':r.get('secondary_v1',{})};runs[block].append(entry)
  for label in entry['primary'].get('rows',[]):
   flat.append({'block':block,'case_index':raw['case_index'],'StudyInstanceUID':raw['StudyInstanceUID'],'language':reports[raw['case_index']]['language'],'condition':label['condition'],'label':label['label'],'confidence':label.get('confidence'),'technical_status':label['status'],'evidence':label.get('source_span') or label.get('model_evidence',''),'reason':label.get('reason'),'generation_seconds':g['runtime_seconds'],'peak_gpu_gib':raw['gpu_peak_allocated_gib']})
if flat:
 with (a.destination/'report_condition_results.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(flat[0]));w.writeheader();w.writerows(flat)
summary={'planned_generations':20,'saved_generations':sum(map(len,runs.values())),'blocks':{},'agreement':{},'medical_accuracy':'NOT EVALUATED; no organizer labels were read','confidence':'Model self-report, not calibrated probability'}
for block,entries in runs.items():
 items=[r for r in flat if r['block']==block];summary['blocks'][block]={'generations':len(entries),'seconds':sum(x['seconds'] for x in entries),'technical_status':dict(collections.Counter(x['technical_status'] for x in items)),'labels':dict(collections.Counter(str(x['label']) for x in items)),'peak_gpu_gib':max((x['peak_gib'] for x in entries),default=0)}
for left,right in [('control-1','candidate-1'),('control-1','control-2'),('candidate-1','candidate-2')]:
 if left not in runs or right not in runs:continue
 l={(x['case_index'],x['condition']):x for x in flat if x['block']==left};r={(x['case_index'],x['condition']):x for x in flat if x['block']==right};pairs=[(l[k],r[k]) for k in l.keys()&r.keys()];valid=[(x,y) for x,y in pairs if x['technical_status']==y['technical_status']=='valid'];summary['agreement'][left+' vs '+right]={'paired_conditions':len(pairs),'both_technically_valid':len(valid),'equal_labels':sum(x['label']==y['label'] for x,y in valid),'excluded_technical_errors':len(pairs)-len(valid),'raw_byte_exact_reports':sum(x['raw']==y['raw'] for x,y in zip(runs[left],runs[right]))}
(a.destination/'summary.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False))
data=json.dumps({'reports':reports,'runs':runs,'summary':summary},ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Qwen report extraction — actual outputs</title><style>
body{font:15px system-ui;margin:0;background:#f3f6fa;color:#16283d}header{padding:24px;background:#172e46;color:white}h1{margin:0 0 8px;font-size:25px}.note{color:#bacbdd}main{padding:20px}.bar{display:flex;gap:12px;margin-bottom:18px}select,button{padding:10px;border:1px solid #bcc9d8;border-radius:7px;background:white}.grid{display:grid;grid-template-columns:38% 62%;gap:16px}.card{padding:18px;background:white;border:1px solid #dae2eb;border-radius:10px;min-width:0}#report{white-space:pre-wrap;line-height:1.65}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:9px;border-bottom:1px solid #e4e9f0;vertical-align:top}tr{cursor:pointer}tr:hover{background:#eef4fb}.positive{color:#176735}.negative{color:#265da3}.uncertain{color:#976608}.not_mentioned{color:#78818d}.error{color:#b23131}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}mark{background:#fff2a3}#metrics{margin:10px 0 16px;color:#536477}.footer{font-size:13px;color:#5d6a79;margin-top:16px}@media(max-width:900px){.grid{grid-template-columns:1fr}}
</style><header><h1>Qwen — MRI report extraction</h1><div class="note">Actual saved outputs · Five development reports · ABBA20 · Original report language preserved</div></header><main><div class="bar"><select id="case"></select><select id="block"></select></div><div id="metrics"></div><div class="grid"><section class="card"><h2>Original report</h2><div id="report"></div><p class="footer">Click a condition to highlight its verified evidence span.</p></section><section class="card"><h2>Extracted conditions</h2><table><thead><tr><th>Condition</th><th>Label / confidence</th><th>Evidence</th><th>Technical status</th></tr></thead><tbody id="rows"></tbody></table><details><summary>Raw model output</summary><pre id="raw"></pre></details></section></div><p class="footer">Technical validity is not medical accuracy. Confidence is model-reported and uncalibrated. not_mentioned remains separate from negative. Technical errors have no accepted label. Semantic review and organizer agreement have not been performed.</p><section class="card"><h2>Technical results by block</h2><table id="blocksummary"></table><h2>Agreement, not medical accuracy</h2><table id="comparison"></table></section><details><summary>Machine-readable summary</summary><pre id="summary"></pre></details></main><script>
const D=DATA; const cs=document.getElementById('case'),bs=document.getElementById('block');D.reports.forEach((r,i)=>cs.add(new Option(`Report ${i+1} · ${r.language}`,i)));Object.keys(D.runs).forEach(b=>bs.add(new Option(b,b)));document.getElementById('summary').textContent=JSON.stringify(D.summary,null,2);
function addRow(table,values){let tr=document.createElement('tr');values.forEach(v=>{let td=document.createElement('td');td.textContent=v;tr.append(td)});table.append(tr)}
const bt=document.getElementById('blocksummary');addRow(bt,['Block','Generations','Valid condition rows','Technical errors','Generation seconds','Peak GiB']);Object.entries(D.summary.blocks).forEach(([b,v])=>addRow(bt,[b,v.generations,v.technical_status.valid||0,Object.entries(v.technical_status).filter(([k])=>k!=='valid').reduce((s,[k,n])=>s+n,0),v.seconds.toFixed(1),v.peak_gpu_gib.toFixed(2)]));const ct=document.getElementById('comparison');addRow(ct,['Comparison','Same label / valid pairs','Excluded errors','Byte-identical reports']);Object.entries(D.summary.agreement).forEach(([k,v])=>addRow(ct,[k,v.equal_labels+' / '+v.both_technically_valid,v.excluded_technical_errors,v.raw_byte_exact_reports+' / 5']));
function render(){let i=+cs.value,e=D.runs[bs.value].find(x=>x.case_index===i),r=D.reports[i];const report=document.getElementById('report');report.textContent=r.Report;document.getElementById('rows').replaceChildren();if(!e){document.getElementById('metrics').textContent='UNRUN';document.getElementById('raw').textContent='';return;}document.getElementById('metrics').textContent=`${bs.value} · ${e.generation_status} · ${e.seconds.toFixed(2)} seconds · ${e.output_tokens} output tokens · ${e.peak_gib.toFixed(2)} GiB peak`;document.getElementById('raw').textContent=e.raw;(e.primary.rows||[]).forEach(x=>{let tr=document.createElement('tr');let values=[x.condition,(x.label===null?'TECHNICAL FAILURE':x.label)+' / '+x.confidence,x.source_span||x.model_evidence||'—',x.status+(x.reason?' · '+x.reason:'')];values.forEach((v,k)=>{let td=document.createElement('td');td.textContent=v;if(k===1)td.className=x.label||'error';if(k===3&&x.status!=='valid')td.className='error';tr.append(td)});tr.onclick=()=>{report.replaceChildren();if(Number.isInteger(x.evidence_start)&&Number.isInteger(x.evidence_end)){report.append(document.createTextNode(r.Report.slice(0,x.evidence_start)));let m=document.createElement('mark');m.textContent=r.Report.slice(x.evidence_start,x.evidence_end);report.append(m,document.createTextNode(r.Report.slice(x.evidence_end)))}else report.textContent=r.Report;};document.getElementById('rows').append(tr);});}cs.onchange=bs.onchange=render;render();
</script>'''.replace('DATA',data)
(a.destination/'case_viewer.html').write_text(page)
print(json.dumps(summary,indent=2))
